/* range fissi per le due scale colore */
const RESIL_RANGE = {res:{min:-0.1416,max:0.1407}, smooth:{min:-0.0771,max:0.0846}};

/* stato vista: false=off, 'res'=residuo, 'smooth'=zone del colle */
let resilMode = false;

const _stile_base = stile;
const _ricolora_base = ricolora;
const _aggLegenda_base = aggLegenda;
const _aggDrawer_resil_base = aggDrawer;

const _GRD_RES = 'linear-gradient(to right,rgb(150,35,32) 0%,rgb(195,110,60) 30%,rgb(214,182,112) 55%,rgb(120,170,95) 80%,rgb(55,140,150) 100%)';
const _COL_ND  = '#3a3a3a';

function coloreRESIL(val, mode){
  if(val==null) return null;
  const r = RESIL_RANGE[mode];
  let t = Math.max(0, Math.min(1, (val - r.min) / ((r.max - r.min) || 1)));
  const stops = [[0,[150,35,32]],[.3,[195,110,60]],[.55,[214,182,112]],[.8,[120,170,95]],[1,[55,140,150]]];
  for(let i=0;i<stops.length-1;i++){const[t0,c0]=stops[i],[t1,c1]=stops[i+1];
    if(t>=t0&&t<=t1){const f=(t-t0)/(t1-t0);
      return `rgb(${Math.round(c0[0]+f*(c1[0]-c0[0]))},${Math.round(c0[1]+f*(c1[1]-c0[1]))},${Math.round(c0[2]+f*(c1[2]-c0[2]))})`;}}
  return '#888';
}

function _resVal(r){ return resilMode==='smooth' ? r.res_smooth : r.res; }

/* override stile: luna (se mai riattivata) > resilienza > base */
stile = function(vid){
  if(typeof notturnoMode!=='undefined' && notturnoMode) return _stile_base(vid);
  if(!resilMode) return _stile_base(vid);
  const sel = vid===vidSel;
  const v = DATI[vid];
  const fuoriScope = v && (v.zona==='Vigna_menzione_Valdobbiadene' || v.zona==='Conferitore');
  if(fuoriScope) return _stile_base(vid);
  const r = RESIL[vid];
  if(!r || r.cat==='nd'){
    return {fillColor:_COL_ND,
      fillOpacity: vidSel&&!sel ? 0.25 : 0.4,
      color: sel ? '#f0d878' : '#1a1a1a',
      weight: sel ? 3 : 0.6};
  }
  const fill = coloreRESIL(_resVal(r), resilMode);
  return {fillColor:fill,
    fillOpacity: vidSel&&!sel ? 0.4 : 0.78,
    color: sel ? '#f0d878' : '#1a1a1a',
    weight: sel ? 3 : 0.7};
};

ricolora = function(){
  if(typeof notturnoMode!=='undefined' && notturnoMode) return _ricolora_base();
  for(const vid in layers){
    layers[vid].setStyle(stile(vid));
    if(resilMode){
      const r = RESIL[vid], v = DATI[vid];
      const nome = (v && v.c ? nomePulito(v.c) : 'Cartizze');
      const fuoriScope = v && (v.zona==='Vigna_menzione_Valdobbiadene' || v.zona==='Conferitore');
      let txt;
      if(fuoriScope){
        txt = etichetta(vid);
      } else if(!r || r.cat==='nd'){
        txt = nome+' \u00b7 esclusa. '+(r?r.motivo:'dato non disponibile');
      } else if(resilMode==='smooth'){
        txt = nome+' \u00b7 zona: '+(r.res_smooth>=0?'+':'')+r.res_smooth.toFixed(3);
      } else {
        txt = nome+' \u00b7 residuo: '+(r.res>=0?'+':'')+r.res.toFixed(3);
      }
      if(layers[vid].getTooltip()) layers[vid].setTooltipContent(txt);
    }
  }
  aggLegenda();
};

aggLegenda = function(){
  if(typeof notturnoMode!=='undefined' && notturnoMode) return _aggLegenda_base();
  if(!resilMode){
    const b = document.querySelector('#legend .leg-bar');
    if(b) b.style.width = '';
    return _aggLegenda_base();
  }
  const t = document.getElementById('leg-title');
  const lo = document.getElementById('leg-lo');
  const hi = document.getElementById('leg-hi');
  const bar = document.querySelector('#legend .leg-bar');
  const note = document.getElementById('leg-note');
  if(resilMode==='smooth'){
    if(t) t.textContent = 'Zone del colle (media coi vicini entro ~50m)';
    if(lo) lo.textContent = 'zona pi\u00f9 fragile';
    if(hi) hi.textContent = 'zona pi\u00f9 resiliente';
    if(bar){ bar.style.background = _GRD_RES; bar.style.backgroundSize = '100% 100%'; bar.style.width = '100%'; }
    if(note) note.textContent = 'il colle si comporta a zone, non a filare isolato (test statistico, non impressione visiva)';
  } else {
    if(t) t.textContent = 'Resilienza 2022 (scostamento dalla norma)';
    if(lo) lo.textContent = 'peggio del solito';
    if(hi) hi.textContent = 'meglio del solito';
    if(bar){ bar.style.background = _GRD_RES; bar.style.backgroundSize = '100% 100%'; bar.style.width = '100%'; }
    if(note) note.textContent = 'come ogni parcella ha retto la siccit\u00e0 2022 rispetto al proprio comportamento normale. grigio = 161 su 553 escluse per dato insufficiente';
  }
};

/* override aggDrawer: quando si clicca una parcella, aggiungo il dettaglio
   "valore grezzo 2022" in coda alla scheda esistente, indipendentemente
   dalla vista attiva (base, resilienza o zone) — sempre visibile su richiesta
   di dettaglio, mai come vista mappa a se'. */
aggDrawer = function(){
  _aggDrawer_resil_base();
  const vid = vidSel;
  if(!vid) return;
  const v = DATI[vid];
  const fuoriScope = v && (v.zona==='Vigna_menzione_Valdobbiadene' || v.zona==='Conferitore');
  const r = RESIL[vid];
  const body = document.getElementById('drawer-body');
  let box = document.getElementById('resil-detail');
  if(fuoriScope){
    if(box) box.remove();
    return;
  }
  if(!box){
    box = document.createElement('div');
    box.id = 'resil-detail';
    box.className = 'syn-block';
    body.appendChild(box);
  }
  if(!r || r.cat === 'nd'){
    box.innerHTML = '<div class="syn-label">Resilienza 2022</div>'
      + '<div style="color:var(--text-mute);font-size:12px;padding:4px 0;">'
      + (r ? 'esclusa. ' + r.motivo : 'dato non disponibile')
      + '</div>';
  } else {
    box.innerHTML = '<div class="syn-label">Resilienza 2022</div>'
      + '<div style="color:var(--text-mute);font-size:12px;padding:4px 0;line-height:1.5;">'
      + 'residuo (scostamento dalla norma): <strong style="color:var(--text)">'+(r.res>=0?'+':'')+r.res.toFixed(3)+'</strong><br>'
      + 'zona (media coi vicini ~50m): <strong style="color:var(--text)">'+(r.res_smooth>=0?'+':'')+r.res_smooth.toFixed(3)+'</strong><br>'
      + 'valore grezzo 2022 (NDMI, non normalizzato): <strong style="color:var(--text)">'+r.delta.toFixed(3)+'</strong>'
      + '</div>';
  }
};

/* ---- UI: due bottoni indipendenti, montati in #view-icons (barra alta) ---- */
function buildResilienzaUI(){
  const iconHost = document.getElementById('view-icons') || document.getElementById('year-area') || document.body;
  const areaHost = document.getElementById('year-area') || document.body;

  const btnRes = document.createElement('button');
  btnRes.id = 'resil-btn';
  btnRes.title = 'Resilienza 2022. scostamento dalla norma per parcella';
  btnRes.textContent = '\u26A1';
  iconHost.appendChild(btnRes);

  const btnZone = document.createElement('button');
  btnZone.id = 'zone-btn';
  btnZone.title = 'Zone del colle. media coi vicini entro ~50m';
  btnZone.textContent = '\uD83C\uDF0A';
  iconHost.appendChild(btnZone);

  const desc = document.createElement('div');
  desc.id = 'resil-desc';
  desc.style.display = 'none';
  areaHost.parentNode.insertBefore(desc, areaHost.nextSibling);

  function setBanner(){
    if(resilMode==='smooth')
      desc.textContent = 'Il colle ha zone distinte largh\u2019 qualche decina di metri, non filari isolati. pattern statisticamente non casuale';
    else
      desc.textContent = 'Quanto ogni parcella si e\u2019 discostata dal proprio comportamento normale nel 2022. 392 su 553, le altre escluse per qualit\u00e0 del dato';
  }

  function enterResil(mode){
    if(typeof notturnoMode!=='undefined' && notturnoMode){
      const mb=document.getElementById('moon-btn'); if(mb) mb.click();
    }
    const gb = document.getElementById('gest-btn');
    if(gb && gb.classList.contains('active')) gb.click();

    resilMode = mode;
    const yb=document.getElementById('year-bar'); if(yb) yb.classList.add('disabled');
    const dt=document.getElementById('drawer-tabs'); if(dt) dt.style.display='none';
    desc.style.display = 'block';
    btnRes.classList.toggle('active', mode==='res');
    btnZone.classList.toggle('active', mode==='smooth');
    setBanner();
    ricolora();
  }
  function exitResil(){
    resilMode = false;
    const yb=document.getElementById('year-bar'); if(yb) yb.classList.remove('disabled');
    const dt=document.getElementById('drawer-tabs'); if(dt) dt.style.display='';
    desc.style.display = 'none';
    btnRes.classList.remove('active');
    btnZone.classList.remove('active');
    aggLegenda();
    ricolora();
  }

  btnRes.onclick = ()=>{ resilMode==='res' ? exitResil() : enterResil('res'); };
  btnZone.onclick = ()=>{ resilMode==='smooth' ? exitResil() : enterResil('smooth'); };

  const moonBtn = document.getElementById('moon-btn');
  if(moonBtn){
    moonBtn.addEventListener('click', ()=>{ if(resilMode) exitResil(); }, true);
  }
}

function avviaResilienza(tentativi){
  tentativi = tentativi || 0;
  const ya = document.getElementById('year-area');
  if(!ya){
    if(tentativi < 20){ setTimeout(()=>avviaResilienza(tentativi+1), 150); return; }
  }
  if(document.getElementById('resil-btn')) return;
  try {
    buildResilienzaUI();
  } catch(e){
    console.error('[resilienza] errore in buildResilienzaUI:', e);
  }
}

if(document.readyState!=='loading') avviaResilienza();
else document.addEventListener('DOMContentLoaded', ()=>avviaResilienza());
